    15	public class App {
    16	
    17	    public static void main(String[] args) {
    18	        AppConfig config = AppConfig.fromEnv(System.getenv());
    19	        Database database = new Database(config.dbUrl(), config.dbUser(), config.dbPassword(), null);
    20	        start(config, database).start(config.port());
    21	    }
