    25	        database.createSchema();
    26	        RoomRepository rooms = new RoomRepository();
    27	        ReservationRepository reservations = new ReservationRepository();
    28	        MessageRepository messages = new MessageRepository();
    29	        database.run(connection -> {
    30	            rooms.seed(connection);
    31	            return null;
