     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	public final class Money {
    10	
    11	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
    12	
    13	    private Money() {
    14	    }
    15	
    16	    /** Arredonda para centavos, meio para o par. */
    17	    public static BigDecimal round(BigDecimal value) {
    18	        return value.setScale(2, RoundingMode.HALF_EVEN);
    19	    }
    20	
    21	    /** Escreve como R$ 1.234,56. */
    22	    public static String brl(BigDecimal value) {
    23	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    24	        symbols.setGroupingSeparator('.');
    25	        symbols.setDecimalSeparator(',');
    26	        return "R$ " + new DecimalFormat("#,##0.00", symbols).format(round(value));
    27	    }
    28	}
