     1	package br.com.marealta.web;
     2	
     3	import br.com.marealta.db.Database;
     4	import br.com.marealta.message.MessageRepository;
     5	import br.com.marealta.reservation.ReportService;
     6	import br.com.marealta.reservation.ReservationService;
     7	import com.fasterxml.jackson.core.JsonProcessingException;
     8	import com.fasterxml.jackson.databind.ObjectMapper;
     9	import io.javalin.Javalin;
    10	import io.javalin.http.Context;
    11	
    12	import java.time.LocalDate;
    13	import java.time.YearMonth;
    14	import java.time.format.DateTimeParseException;
    15	import java.util.LinkedHashMap;
    16	import java.util.Map;
    17	
    18	public class Routes {
    19	
    20	    private static final ObjectMapper MAPPER = new ObjectMapper();
    21	
    22	    private final ReservationService reservations;
    23	    private final ReportService reports;
    24	    private final MessageRepository messages;
    25	    private final Database database;
    26	
    27	    public Routes(ReservationService reservations, ReportService reports, MessageRepository messages,
    28	                  Database database) {
    29	        this.reservations = reservations;
    30	        this.reports = reports;
    31	        this.messages = messages;
    32	        this.database = database;
    33	    }
    34	
    35	    public void register(Javalin app) {
    36	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    37	        app.exception(Exception.class, (e, ctx) -> {
    38	            e.printStackTrace();
    39	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    40	        });
    41	        app.error(404, ctx -> {
    42	            if (ctx.result() == null || ctx.result().isEmpty()) {
    43	                error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
    44	            }
    45	        });
    46	
    47	        app.get("/rooms", ctx -> json(ctx, 200, reservations.rooms().stream().map(Views::room).toList()));
    48	        app.post("/reservations", ctx -> json(ctx, 201, Views.reservation(
    49	                reservations.create(ReservationRequestParser.parse(MAPPER, ctx.body())))));
    50	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Views.reservation(reservations.get(id(ctx)))));
    51	        app.post("/reservations/{id}/confirmation",
    52	                ctx -> json(ctx, 200, Views.reservation(reservations.confirm(id(ctx)))));
    53	        app.post("/reservations/{id}/cancellation",
    54	                ctx -> json(ctx, 200, Views.reservation(reservations.cancel(id(ctx)))));
    55	        app.post("/reservations/{id}/check-in",
    56	                ctx -> json(ctx, 200, Views.reservation(reservations.checkIn(id(ctx)))));
    57	        app.post("/reservations/{id}/check-out",
    58	                ctx -> json(ctx, 200, Views.receipt(reservations.checkOut(id(ctx)))));
    59	        app.get("/reservations/{id}/document",
    60	                ctx -> json(ctx, 200, Views.receipt(reservations.document(id(ctx)))));
    61	        app.get("/messages", ctx -> json(ctx, 200,
    62	                database.run(messages::all).stream().map(Views::message).toList()));
    63	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(date(ctx.queryParam("date")))));
    64	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(month(ctx.queryParam("month")))));
    65	    }
    66	
    67	    private static String id(Context ctx) {
    68	        return ctx.pathParam("id");
    69	    }
    70	
    71	    private static LocalDate date(String value) {
    72	        try {
    73	            return LocalDate.parse(value == null ? "" : value);
    74	        } catch (DateTimeParseException e) {
    75	            throw ApiException.invalidRequest("Data inválida, use o formato 2027-07-10");
    76	        }
    77	    }
    78	
    79	    private static YearMonth month(String value) {
    80	        try {
    81	            return YearMonth.parse(value == null ? "" : value);
    82	        } catch (DateTimeParseException e) {
    83	            throw ApiException.invalidRequest("Mês inválido, use o formato 2027-07");
    84	        }
    85	    }
    86	
    87	    private static void csv(Context ctx, String body) {
    88	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    89	    }
    90	
    91	    private static void error(Context ctx, int status, String code, String message) {
    92	        Map<String, Object> body = new LinkedHashMap<>();
    93	        body.put("error", code);
    94	        body.put("message", message);
    95	        json(ctx, status, body);
    96	    }
    97	
    98	    private static void json(Context ctx, int status, Object body) {
    99	        try {
   100	            ctx.status(status).contentType("application/json; charset=utf-8").result(MAPPER.writeValueAsString(body));
   101	        } catch (JsonProcessingException e) {
   102	            throw new IllegalStateException(e);
   103	        }
   104	    }
   105	}
