    10	public class Database implements AutoCloseable {
    11	
    12	    public interface Work<T> {
    13	        T run(Connection connection) throws SQLException;
    14	    }
    15	
    16	    private static final String SCHEMA_SQL = """
    17	            create table if not exists rooms (
    18	                number integer primary key,
    19	                type text not null,
    20	                capacity integer not null,
    21	                nightly_rate numeric(12,2) not null
    22	            );
    23	            create table if not exists reservations (
    24	                id bigserial primary key,
    25	                room_number integer not null references rooms(number),
    26	                guest_name text not null,
    27	                guest_email text not null,
    28	                guest_cpf text not null,
    29	                check_in date not null,
    30	                check_out date not null,
    31	                guests integer not null,
    32	                rate_plan text not null,
    33	                nights integer not null,
    34	                subtotal numeric(12,2) not null,
    35	                discount numeric(12,2) not null,
    36	                total numeric(12,2) not null,
    37	                status text not null,
    38	                amount_paid numeric(12,2) not null,
    39	                refund numeric(12,2)
    40	            );
    41	            create index if not exists reservations_room_idx on reservations(room_number, check_in);
    42	            create table if not exists messages (
    43	                id bigserial primary key,
    44	                channel text not null,
    45	                recipient text not null,
    46	                subject text not null,
    47	                body text not null,
    48	                status text not null
    49	            );
    50	            """;
    51	
    52	    private final HikariDataSource dataSource;
    53	
    54	    /** O esquema é opcional: permite isolar os dados (usado nos testes). */
    55	    public Database(String url, String user, String password, String schema) {
    56	        HikariConfig config = new HikariConfig();
    57	        config.setJdbcUrl(url);
    58	        config.setUsername(user);
    59	        config.setPassword(password);
    60	        config.setMaximumPoolSize(10);
    61	        config.setConnectionTimeout(10_000);
    62	        config.setInitializationFailTimeout(60_000);
    63	        if (schema != null) {
    64	            config.setConnectionInitSql("set search_path to " + schema);
    65	        }
    66	        this.dataSource = new HikariDataSource(config);
    67	    }
    68	
    69	    public void createSchema() {
    70	        run(connection -> {
    71	            try (Statement statement = connection.createStatement()) {
    72	                statement.execute("select pg_advisory_xact_lock(7070)");
    73	                statement.execute(SCHEMA_SQL);
    74	            }
    75	            return null;
    76	        });
    77	    }
    78	
    79	    /** Executa tudo numa transação: ou entra tudo, ou nada. */
    80	    public <T> T run(Work<T> work) {
    81	        try (Connection connection = dataSource.getConnection()) {
    82	            connection.setAutoCommit(false);
    83	            try {
    84	                T result = work.run(connection);
    85	                connection.commit();
    86	                return result;
    87	            } catch (Throwable e) {
    88	                connection.rollback();
    89	                throw e;
    90	            }
    91	        } catch (SQLException e) {
    92	            throw new IllegalStateException("Falha no banco de dados: " + e.getMessage(), e);
    93	        }
    94	    }
    95	
    96	    @Override
    97	    public void close() {
    98	        dataSource.close();
    99	    }
