     9	/** Comprovante de reserva: serve para o e-mail, o check-out e a segunda via. */
    10	public record Receipt(long reservationId, String guestName, String guestCpf, int roomNumber, String roomType,
    11	                      LocalDate checkIn, LocalDate checkOut, int nights, BigDecimal subtotal,
    12	                      BigDecimal discount, BigDecimal total) {
    13	
    14	    public static final String TITLE = "Comprovante de reserva";
    15	    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    16	
    17	    public static Receipt of(Reservation reservation, Room room) {
    18	        return new Receipt(reservation.id(), reservation.guestName(), reservation.guestCpf(), room.number(),
    19	                room.type(), reservation.checkIn(), reservation.checkOut(), reservation.nights(),
    20	                reservation.subtotal(), reservation.discount(), reservation.total());
    21	    }
    22	
    23	    public String text() {
    24	        StringBuilder text = new StringBuilder();
    25	        text.append(TITLE).append(" nº ").append(reservationId).append('\n');
    26	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
    27	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
    28	        text.append("Entrada: ").append(DATE.format(checkIn)).append(" | Saída: ").append(DATE.format(checkOut))
