    38	            }
    39	            if (reservations.overlaps(connection, room.number(), request.checkIn(), request.checkOut())) {
    40	                throw ApiException.roomUnavailable(room.number());
    41	            }
    42	            Pricing.Quote quote = Pricing.quote(room.nightlyRate(), request.checkIn(), request.checkOut(),
    43	                    request.ratePlan());
    44	            return reservations.insert(connection, new Reservation(null, room.number(), request.guestName(),
    45	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    46	                    request.guests(), request.ratePlan(), quote.nights(), quote.subtotal(), quote.discount(),
    47	                    quote.total(), Status.PENDING, Money.ZERO, null));
    48	        });
    49	    }
