     9	/** Preço das noites: diária do quarto, com acréscimo na alta temporada, e desconto do plano. */
    10	public final class Pricing {
    11	
    12	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    13	
    14	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    15	    }
    16	
    17	    private Pricing() {
    18	    }
    19	
    20	    /** Alta temporada: de 15 de dezembro ao fim de fevereiro, e julho inteiro. */
    21	    public static boolean isHighSeason(LocalDate night) {
    22	        Month month = night.getMonth();
    23	        return month == Month.JULY
    24	                || month == Month.JANUARY
    25	                || month == Month.FEBRUARY
    26	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    27	    }
    28	
    29	    public static BigDecimal nightPrice(BigDecimal nightlyRate, LocalDate night) {
    30	        return isHighSeason(night) ? Money.round(nightlyRate.multiply(HIGH_SEASON_FACTOR)) : Money.round(nightlyRate);
    31	    }
    32	
    33	    public static Quote quote(BigDecimal nightlyRate, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    34	        BigDecimal subtotal = Money.ZERO;
    35	        int nights = 0;
