     1	package br.com.marealta.message;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.Locale;
     6	import java.util.Map;
     7	import java.util.function.Supplier;
     8	
     9	/**
    10	 * Regras que existem e como cada instalação as combina. A configuração é uma lista "regra[:escopo]" separada
    11	 * por vírgulas, na ordem de execução; escopo é always, test ou live. Regra nova entra aqui, numa linha só.
    12	 */
    13	public final class RuleCatalog {
    14	
    15	    public static final String DEFAULT_SPEC = "address-validation,test-redirect:test,archive-copy:live";
    16	
    17	    private static final Map<String, Supplier<MessageRule>> AVAILABLE = Map.of(
    18	            "address-validation", AddressValidationRule::new,
    19	            "test-redirect", () -> new TestRedirectRule("testes@pousadamarealta.com.br"),
    20	            "archive-copy", () -> new ArchiveCopyRule("arquivo@pousadamarealta.com.br"));
    21	
    22	    private static final Map<String, RuleScope> SCOPES = Map.of(
    23	            "always", RuleScope.ALWAYS,
    24	            "test", RuleScope.TEST_ONLY,
    25	            "live", RuleScope.LIVE_ONLY);
    26	
    27	    private RuleCatalog() {
    28	    }
    29	
    30	    public static List<ConfiguredRule> parse(String spec) {
    31	        String effective = spec == null || spec.isBlank() ? DEFAULT_SPEC : spec;
    32	        List<ConfiguredRule> rules = new ArrayList<>();
    33	        for (String item : effective.split(",")) {
    34	            if (item.isBlank()) {
    35	                continue;
    36	            }
    37	            String[] parts = item.trim().split(":", 2);
    38	            Supplier<MessageRule> rule = AVAILABLE.get(parts[0].trim());
    39	            if (rule == null) {
    40	                throw new IllegalArgumentException("Regra de mensagem desconhecida: " + parts[0]);
    41	            }
    42	            RuleScope scope = parts.length == 1 ? RuleScope.ALWAYS : SCOPES.get(parts[1].trim().toLowerCase(Locale.ROOT));
    43	            if (scope == null) {
    44	                throw new IllegalArgumentException("Escopo desconhecido: " + parts[1]);
    45	            }
    46	            rules.add(new ConfiguredRule(rule.get(), scope));
    47	        }
    48	        return rules;
    49	    }
    50	}
